213	// decodeJSONBody enforces the strict POST contract shared by every JSON
214	// endpoint: Content-Type must be application/json, the body is capped at
215	// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
216	// may follow it. Any violation writes a 400 JSON error and returns false; the
217	// caller returns immediately, so no handler reaches the store with malformed
218	// input and rejected requests write nothing.
219	func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
220		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
221		if err != nil || mediaType != "application/json" {
222			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
223			return false
224		}
225	
226		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
227		dec := json.NewDecoder(r.Body)
228		if err := dec.Decode(dst); err != nil {
229			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
230			return false
231		}
232		// Reject trailing data after the JSON value.
233		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
234			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
235			return false
236		}
237		return true
238	}
