385			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
386			return
387		}
388	
389		if req.DeviceID == "" {
390			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
391			return
392		}
393		// baseCursor must be present and a non-negative integer (no fractions,
394		// strings, booleans or null).
395		if len(req.BaseCursor) == 0 {
396			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
397			return
398		}
399		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
400		if !ok {
401			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
402			return
403		}
404		if req.Change == nil {
405			writeError(w, http.StatusBadRequest, "change must be an object")
406			return
407		}
408		if req.Change.ID == "" {
409			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
410			return
411		}
412		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
413			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
414			return
415		}
416	
417		result, err := s.MergeChange(documentID, baseCursor, store.Change{
418			ID:       req.Change.ID,
419			DeviceID: req.DeviceID,
420			Payload:  req.Change.Payload,
421		})
422		if err != nil {
423			var conflict *store.ErrConflict
424			switch {
425			case errors.Is(err, store.ErrStaleCursor):
426				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
427				return
428			case errors.As(err, &conflict):
429				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
430				return
431			default:
432				writeError(w, http.StatusInternalServerError, "failed to merge change")
433				return
434			}
435		}
436	
437		writeJSON(w, http.StatusOK, result)
438	}
439	
440	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
441		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
442	
443		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
444		if err != nil || mediaType != "application/json" {
445			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
446			return
447		}
448	
449		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
450		var req snapshotPostRequest
451		dec := json.NewDecoder(r.Body)
452		if err := dec.Decode(&req); err != nil {
453			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
454			return
455		}
456		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
457			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
458			return
459		}
460	
461		cursor, ok := parseNonNegativeInt(req.Cursor)
462		if !ok {
463			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
464			return
465		}
466		if len(req.State) == 0 {
467			writeError(w, http.StatusBadRequest, "state is required")
468			return
469		}
470	
471		created, err := s.PutSnapshot(documentID, cursor, req.State)
472		if err != nil {
473			var conflict *store.ErrSnapshotConflict
474			switch {
475			case errors.Is(err, store.ErrSnapshotBase):
476				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
477				return
478			case errors.As(err, &conflict):
479				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
480				return
481			default:
482				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
483				return
484			}
485		}
486	
487		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
488	}
489	
490	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
491		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
492	
493		cursor, ok := parseCursorPath(r.PathValue("cursor"))
494		if !ok {
495			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
496			return
497		}
498	
499		state, err := s.GetSnapshot(documentID, cursor)
500		if err != nil {
501			if errors.Is(err, store.ErrSnapshotNotFound) {
502				writeError(w, http.StatusNotFound, "snapshot not found")
503				return
504			}
505			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
506			return
507		}
508	
509		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
510	}
511	
512	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
513		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
514	
515		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
516		if err != nil || mediaType != "application/json" {
517			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
518			return
519		}
520	
521		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
522		var req restoreRequest
523		dec := json.NewDecoder(r.Body)
524		if err := dec.Decode(&req); err != nil {
525			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
526			return
527		}
528		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
529			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
530			return
531		}
532	
533		if req.DeviceID == "" {
534			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
535			return
536		}
537		if req.ChangeID == "" {
538			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
539			return
540		}
541		// snapshotCursor must be present and a positive integer (no fractions,
542		// strings, booleans, null or zero).
543		if len(req.SnapshotCursor) == 0 {
544			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
545			return
546		}
547		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
548		if !ok {
549			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
550			return
551		}
552	
553		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
554		if err != nil {
555			var conflict *store.ErrRestoreConflict
556			switch {
557			case errors.Is(err, store.ErrSnapshotNotFound):
558				writeError(w, http.StatusNotFound, "snapshot not found")
559				return
560			case errors.As(err, &conflict):
561				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
562				return
563			default:
564				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
565				return
566			}
567		}
568	
569		writeJSON(w, http.StatusOK, result)
570	}
571	
572	// handleSetPermission grants or revokes a registered device's access to one
573	// document. Devices start authorized, so the first revoke is the first write;
574	// repeating the current state is idempotent (changed=false). A rejected
575	// request (bad content type, malformed JSON, trailing content, empty or
576	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
577	// unregistered device is a 404 JSON error.
578	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
579		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
580	
581		var req permissionRequest
582		if !decodeJSONBody(w, r, &req) {
583			return
584		}
585		if req.DeviceID == "" {
586			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
587			return
588		}
589		var authorized bool
590		switch req.Action {
591		case "grant":
592			authorized = true
593		case "revoke":
594			authorized = false
595		default:
596			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
597			return
598		}
599	
600		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
601		if err != nil {
602			if errors.Is(err, store.ErrDeviceNotFound) {
603				writeError(w, http.StatusNotFound, "device not found")
604				return
605			}
606			writeError(w, http.StatusInternalServerError, "failed to update permission")
607			return
608		}
609	
610		writeJSON(w, http.StatusOK, map[string]any{
611			"deviceId":   req.DeviceID,
612			"authorized": authorized,
613			"changed":    changed,
614		})
615	}
616	
617	// parseCursorPath reports whether raw is a decimal non-negative integer and
618	// returns its value. Signs, fractions and other adornments are rejected.
619	func parseCursorPath(raw string) (int64, bool) {
620		if raw == "" {
621			return 0, false
622		}
623		for _, c := range raw {
624			if c < '0' || c > '9' {
625				return 0, false
626			}
627		}
628		n, err := strconv.ParseInt(raw, 10, 64)
629		if err != nil {
630			return 0, false
631		}
632		return n, true
633	}
634	
635	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
636	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
637		var n int64
638		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
639			return 0, false
640		}
641		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
642		// require the literal to contain no fraction or exponent.
643		trimmed := strings.TrimSpace(string(raw))
644		if trimmed == "" || trimmed[0] == '-' {
645			return 0, false
646		}
647		for _, c := range trimmed {
648			if c < '0' || c > '9' {
649				return 0, false
650			}
651		}
652		return n, true
653	}
654	
655	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
656	// strings, booleans, null and negative numbers are rejected.
657	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
658		n, ok := parseNonNegativeInt(raw)
659		if !ok || n < 1 {
660			return 0, false
661		}
662		return n, true
663	}
664	
665	// isJSONObject reports whether raw decodes to a JSON object (not null, an
666	// array or a scalar).
667	func isJSONObject(raw json.RawMessage) bool {
668		var m map[string]json.RawMessage
669		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
670			return false
671		}
672		return true
673	}
674	
675	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
676		documentID := r.PathValue("documentID")
677	
678		after, limit, ok := parseChangesQuery(w, r)
679		if !ok {
680			return
681		}
682	
683		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
684		if err != nil {
685			writeError(w, http.StatusInternalServerError, "failed to list changes")
686			return
687		}
688	
689		writeChangesPage(w, changes, nextCursor)
690	}
691	
692	// handleSessionChanges is the session-scoped view of the existing change log:
693	// both path identifiers must be non-empty (the empty-segment guard rejects
694	// those before routing) and the session must currently exist, after which the
695	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
696	// the session's device has been revoked permission for the document, which is
697	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
698	// read; the change log itself is untouched.
699	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
700		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
701		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
702	
703		// Malformed query parameters are a request-shape error (400) checked
704		// before the resource lookup (404), matching the snapshot GET ordering.
705		after, limit, ok := parseChangesQuery(w, r)
706		if !ok {
707			return
708		}
709	
710		deviceID, err := s.SessionDevice(sessionID)
711		if err != nil {
712			if errors.Is(err, store.ErrSessionNotFound) {
713				writeError(w, http.StatusNotFound, "session not found")
714				return
715			}
716			writeError(w, http.StatusInternalServerError, "failed to look up session")
717			return
718		}
719	
720		authorized, err := s.DocumentAuthorized(documentID, deviceID)
721		if err != nil {
722			writeError(w, http.StatusInternalServerError, "failed to look up permission")
723			return
724		}
725		if !authorized {
726			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
727			return
728		}
729	
730		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
731		if err != nil {
732			writeError(w, http.StatusInternalServerError, "failed to list changes")
733			return
734		}
735	
736		writeChangesPage(w, changes, nextCursor)
737	}
738	
739	// parseChangesQuery parses the shared after/limit pagination parameters,
740	// writing the documented 400 on an illegal value. It is shared by the
741	// document-scoped and session-scoped change listings so their query semantics
742	// cannot drift apart.
743	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
744		q := r.URL.Query()
745	
746		after = 0
747		if raw := q.Get("after"); raw != "" {
748			v, err := strconv.ParseInt(raw, 10, 64)
749			if err != nil || v < 0 {
750				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
751				return 0, 0, false
752			}
753			after = v
754		}
755	
756		limit = defaultListLimit
757		if raw := q.Get("limit"); raw != "" {
758			v, err := strconv.ParseInt(raw, 10, 64)
759			if err != nil || v < 1 || v > maxListLimit {
760				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
761				return 0, 0, false
762			}
763			limit = v
764		}
765	
766		return after, limit, true
767	}
768	
769	// writeChangesPage renders a change listing page in the shared response shape.
770	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
771		writeJSON(w, http.StatusOK, map[string]any{
772			"changes":    changes,
773			"nextCursor": nextCursor,
774		})
775	}
776	
777	func writeJSON(w http.ResponseWriter, status int, v any) {
778		w.Header().Set("Content-Type", "application/json")
779		w.WriteHeader(status)
780		_ = json.NewEncoder(w).Encode(v)
781	}
782	
783	func writeError(w http.ResponseWriter, status int, message string) {
784		writeJSON(w, status, map[string]string{"error": message})
785	}
