func (s *Store) Close() error {
	s.notifier.close()
	return s.db.Close()
}

// SubscribeChanges registers ch to be signaled whenever documentID gains a
// committed change (a normal batch, a merge or a restore). The returned
// function unsubscribes. Signals coalesce, so callers re-read the log after
// each wake rather than counting signals.
func (s *Store) SubscribeChanges(documentID string, ch chan struct{}) func() {
	return s.notifier.subscribe(documentID, ch)
}

// WaitForChanges blocks until documentID gains a committed change after the
// subscription is established, ctx is canceled (client disconnect or server
// shutdown) or the wait elapses. It returns true when a change was signaled.
// The caller always re-reads the log on a true result, since signals coalesce
// and the log is authoritative.
func (s *Store) WaitForChanges(ctx context.Context, documentID string, wait time.Duration) bool {
	ch := make(chan struct{}, 1)
	unsubscribe := s.SubscribeChanges(documentID, ch)
	defer unsubscribe()

	if wait <= 0 {
		select {
		case <-ch:
			return true
		case <-ctx.Done():
			return false
		}
	}
	timer := time.NewTimer(wait)
	defer timer.Stop()
	select {
	case <-ch:
		return true
	case <-timer.C:
		return false
	case <-ctx.Done():
		return false
	}
}

