package server

import (
	"errors"
	"net/http"
	"strconv"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// maxWaitMs bounds a long poll (inclusive): the spec allows 0..30000 ms.
const maxWaitMs = 30000

// handlePollChanges is the waiting counterpart of handleListChanges. It
// returns committed changes past after in cursor order, using the same after/
// limit constraints and the same response shape, plus a timedOut flag.
//
//   - Changes already present return immediately, one page, timedOut=false.
//   - An unknown document returns immediately with an empty list, cursor 0
//     and timedOut=false; it never waits.
//   - A known document caught up at its tail holds the request for at most
//     waitMs milliseconds; the first committed change wakes it and the same
//     page is returned. Expiry yields an empty list, nextCursor == after and
//     timedOut=true — the cursor is never advanced by waiting alone.
//
// The wait is canceled by a client disconnect (r.Context) or server shutdown
// (the store's shutdown channel); a canceled wait writes nothing and has of
// course written no changes, cursors or other records.
func handlePollChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	// after/limit share the exact rules of the non-waiting change listing.
	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}

	var waitMs int64
	if raw := r.URL.Query().Get("waitMs"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 || v > maxWaitMs {
			writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
			return
		}
		waitMs = v
	}

	changes, nextCursor, err := s.ListChanges(documentID, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list changes")
		return
	}

	timedOut := false
	if len(changes) == 0 {
		known, err := s.DocumentExists(documentID)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "failed to look up document")
			return
		}
		// An unknown document never waits: empty list, cursor 0.
		if known {
			if waitMs == 0 {
				// The deadline is zero: the wait ends immediately with no
				// data, which is a timeout rather than delivered data.
				timedOut = true
			} else {
				changes, nextCursor, timedOut = waitForChanges(r, s, documentID, after, limit, waitMs)
				if !waitCompleted(r) {
					// Client disconnected or the server is shutting down:
					// write nothing. No state was produced by the wait.
					return
				}
			}
		}
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
		"timedOut":   timedOut,
	})
}

// waitForChanges subscribes to the document's change notifications and blocks
// until the first committed change wakes it, the deadline elapses, the client
// disconnects or the server shuts down. It returns the fresh page (possibly
// empty), the cursor to resume from, and whether the deadline expired.
//
// The subscription is established before the re-read so a commit landing in
// the gap between the caller's list and the subscription cannot be lost: the
// row is either visible to the re-read or its notification is buffered.
func waitForChanges(r *http.Request, s *store.Store, documentID string, after, limit, waitMs int64) (
	changes []store.ListedChange, nextCursor int64, timedOut bool,
) {
	wake := make(chan struct{}, 1)
	unsubscribe := s.SubscribeChanges(documentID, wake)
	defer unsubscribe()

	// Close the subscribe/list race before settling in to wait.
	changes, nextCursor, err := s.ListChanges(documentID, after, limit)
	if err != nil {
		// Mirror the handler's 500 for an unreadable log; the caller treats a
		// non-nil error as a completed wait carrying no page.
		return nil, after, false
	}
	if len(changes) > 0 {
		return changes, nextCursor, false
	}

	timer := time.NewTimer(time.Duration(waitMs) * time.Millisecond)
	defer timer.Stop()
	select {
	case <-wake:
		// A commit landed (signals coalesce): read the authoritative page.
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		if err != nil {
			return nil, after, false
		}
		// The wake may have been a shutdown signal with no new rows; the
		// caller distinguishes cancellation via the request/store channels.
		return changes, nextCursor, len(changes) == 0
	case <-timer.C:
		// Nothing committed in time: keep the original cursor, report timeout.
		return changes, after, true
	case <-r.Context().Done():
		return nil, after, false
	case <-s.ShutdownChannel():
		return nil, after, false
	}
}

// waitCompleted reports whether waitForChanges returned because data arrived
